67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 AddressNormalizer addressNormalizer,
94	                                 EmailNormalizer emailNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        return withOwner(ownerId, owner ->
123	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
130	        rejectBlankOwnerFields(ownerFieldsDto);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
133	        rejectCityAtCapacity(ownerFieldsDto.getCity());
134	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
135	        rejectDailyRegistrationLimit(registrationDate);
136	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
137	        ownerFieldsDto.setTelephone(normalizedTelephone);
138	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
139	        ownerFieldsDto.setEmail(normalizedEmail);
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setRegistrationDate(registrationDate);
143	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
144	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
145	        if (sharesHousehold) {
146	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
147	        }
148	        rejectDuplicateIdentity(owner);
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
152	            ownerMapper.membershipLevel(owner));
153	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        return withOwner(ownerId, currentOwner -> {
163	            currentOwner.setAddress(ownerFieldsDto.getAddress());
164	            currentOwner.setCity(ownerFieldsDto.getCity());
165	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	            currentOwner.setLastName(ownerFieldsDto.getLastName());
167	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
168	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
169	            this.clinicService.saveOwner(currentOwner);
170	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	        });
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Transactional
176	    @Override
177	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
178	        return withOwner(ownerId, owner -> {
179	            this.clinicService.deleteOwner(owner);
180	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	        });
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        return withOwner(ownerId, owner -> {
188	            HttpHeaders headers = new HttpHeaders();
189	            Pet pet = petMapper.toPet(petFieldsDto);
190	            owner.setId(ownerId);
191	            pet.setOwner(owner);
192	            pet.getType().setName(null);
193	            this.clinicService.savePet(pet);
194	            PetDto petDto = petMapper.toPetDto(pet);
195	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
196	                .buildAndExpand(pet.getId()).toUri());
197	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
198	        });
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner != null) {
206	            Pet currentPet = this.clinicService.findPetById(petId);
207	            if (currentPet != null) {
208	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
209	                currentPet.setName(petFieldsDto.getName());
210	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
211	                this.clinicService.savePet(currentPet);
212	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
221	        HttpHeaders headers = new HttpHeaders();
222	        Visit visit = visitMapper.toVisit(visitFieldsDto);
223	        Pet pet = new Pet();
224	        pet.setId(petId);
225	        visit.setPet(pet);
226	        this.clinicService.saveVisit(visit);
227	        VisitDto visitDto = visitMapper.toVisitDto(visit);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
229	            .buildAndExpand(visit.getId()).toUri());
230	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
231	    }
232	
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner != null) {
239	            Pet pet = owner.getPet(petId);
240	            if (pet != null) {
241	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
242	            }
243	        }
244	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	    }
246	
247	    /**
248	     * Loads the owner with the given id and, when it exists, produces the response through
249	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
250	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
251	     * the not-found response are written in exactly one place rather than copied into each method.
252	     *
253	     * @param ownerId the id of the owner to load
254	     * @param action builds the response for an existing owner
255	     * @param <T> the response body type
256	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
257	     */
258	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        return action.apply(owner);
264	    }
265	
266	    /**
267	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
268	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
269	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
270	     * return their owner through this method, so an owner is decorated identically on either path
271	     * and each derived field is computed in exactly one place.
272	     *
273	     * @param owner the persisted owner to represent
274	     * @return the owner DTO with its derived read-only fields populated
275	     */
276	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
277	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
278	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
279	        ownerDto.setIdentityKey(identityKey(owner));
280	        return ownerDto;
281	    }
282	
283	    /**
284	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
285	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
286	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
287	     * blank (e.g. {@code "   "}). The offending field names are reported through an
288	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
289	     * as a 400 response carrying an {@code errors} array of field names.
290	     *
291	     * @param ownerFieldsDto the submitted owner fields
292	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
293	     */
294	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> blankFields = new ArrayList<>();
296	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
297	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
298	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
299	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
300	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
301	        if (!blankFields.isEmpty()) {
302	            throw new InvalidOwnerFieldsException(blankFields);
303	        }
304	    }
305	
306	    private void addIfBlank(List<String> blankFields, String field, String value) {
307	        if (value != null && value.isBlank()) {
308	            blankFields.add(field);
309	        }
310	    }
311	
312	    /**
313	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
314	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
315	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
316	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
317	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
318	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
319	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
320	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
321	     *
322	     * @param city the city of the owner being created
323	     * @param postcode the supplied postcode, or {@code null} when omitted
324	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
325	     */
326	    private void rejectInvalidPostcode(String city, String postcode) {
327	        if (postcode == null || postcode.isBlank()) {
328	            return;
329	        }
330	        Region.forCity(city).ifPresent(region -> {
331	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
332	                throw new InvalidOwnerPostcodeException(postcode, city);
333	            }
334	        });
335	    }
336	
337	    /**
338	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
339	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
340	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
341	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
342	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
343	     *
344	     * @param city the city of the owner being created
345	     * @param lastName the last name of the owner being created
346	     * @return the formatted customer code
347	     */
348	    private String nextCustomerCode(String city, String lastName) {
349	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
350	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
351	        long sequence = ownersInCity(city) + 1L;
352	        return String.format("%s-%s-%04d", city3, last3, sequence);
353	    }
354	
355	    /**
356	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
357	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
358	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
359	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
360	     * new owner and surfaced as the read-only {@code namesakeCount} field.
361	     *
362	     * @param firstName the first name of the owner being created
363	     * @param lastName the last name of the owner being created
364	     * @return the number of existing owners with the same first and last name (case-insensitive)
365	     */
366	    private int namesakeCount(String firstName, String lastName) {
367	        return (int) this.clinicService.findAllOwners().stream()
368	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
369	                && equalsIgnoreCase(owner.getLastName(), lastName))
370	            .count();
371	    }
372	
373	    private boolean equalsIgnoreCase(String a, String b) {
374	        return a == null ? b == null : a.equalsIgnoreCase(b);
375	    }
376	
377	    /**
378	     * The maximum number of owners a single city may contain. Once a city already holds this many
379	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
380	     */
381	    private static final long MAX_OWNERS_PER_CITY = 50L;
382	
383	    /**
384	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
385	     * owners. Existing owners are matched to the requested city case-insensitively (using
386	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
387	     * the per-city counting used for the customer code. A city at capacity is reported through an
388	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
389	     * 409 Conflict response.
390	     *
391	     * @param city the city of the owner being created
392	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
393	     */
394	    private void rejectCityAtCapacity(String city) {
395	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
396	            throw new OwnerCityAtCapacityException(city);
397	        }
398	    }
399	
400	    /**
401	     * Counts the existing owners whose {@code city} matches the given city, compared
402	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Shared by the per-city
403	     * customer-code sequence ({@link #nextCustomerCode(String, String)}) and the per-city capacity
404	     * check ({@link #rejectCityAtCapacity(String)}) so both count a city's owners identically.
405	     *
406	     * @param city the city to count owners for
407	     * @return the number of existing owners in that city
408	     */
409	    private long ownersInCity(String city) {
410	        return this.clinicService.findAllOwners().stream()
411	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
412	            .count();
413	    }
414	
415	    /**
416	     * The maximum number of owners that may be registered on a single day. Once this many owners
417	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
418	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
419	     */
420	    private static final long MAX_OWNERS_PER_DAY = 100L;
421	
422	    /**
423	     * Resolves the effective registration date for a create request: the value supplied in the
424	     * request when present, otherwise the server's current date. The result is the raw effective
425	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
426	     *
427	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
428	     * @return the supplied date, or today when none was supplied
429	     */
430	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
431	        return suppliedDate != null ? suppliedDate : LocalDate.now();
432	    }
433	
434	    /**
435	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
436	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
437	     * the effective registration date so that a weekend value - whether supplied in the request or
438	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
439	     * registration date (such as the membership number's year segment and the daily create-limit
440	     * bucket) uses the adjusted business day.
441	     *
442	     * @param date the effective registration date
443	     * @return the same date when it is a weekday, otherwise the next Monday
444	     */
445	    private LocalDate businessDay(LocalDate date) {
446	        DayOfWeek dayOfWeek = date.getDayOfWeek();
447	        if (dayOfWeek == DayOfWeek.SATURDAY) {
448	            return date.plusDays(2);
449	        }
450	        if (dayOfWeek == DayOfWeek.SUNDAY) {
451	            return date.plusDays(1);
452	        }
453	        return date;
454	    }
455	
456	    /**
457	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
458	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
459	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
460	     * renders as a 429 Too Many Requests response.
461	     *
462	     * @param date the registration date of the owner being created (today)
463	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
464	     */
465	    private void rejectDailyRegistrationLimit(LocalDate date) {
466	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
467	            throw new DailyOwnerRegistrationLimitException(date);
468	        }
469	    }
470	
471	    /**
472	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
473	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
474	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
475	     * day's owners identically.
476	     *
477	     * @param date the registration date to count owners for
478	     * @return the number of existing owners registered on that day
479	     */
480	    private long ownersRegisteredOn(LocalDate date) {
481	        return this.clinicService.findAllOwners().stream()
482	            .filter(owner -> date.equals(owner.getRegistrationDate()))
483	            .count();
484	    }
485	
486	    /**
487	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
488	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
489	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
490	     */
491	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
492	
493	    /**
494	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
495	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
496	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
497	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
498	     * without a registration date, such as seed data) is never flagged.
499	     *
500	     * @param date the owner's registration date (the day it was created), or {@code null}
501	     * @return {@code true} if the day already holds more than the warning threshold of owners
502	     */
503	    private boolean bulkSignupWarning(LocalDate date) {
504	        if (date == null) {
505	            return false;
506	        }
507	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
508	    }
509	
510	    /**
511	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
512	     * The identity key consolidates the former separate telephone, email and household duplicate
513	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
514	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
