94	     * @param telephone a stored or submitted telephone, or {@code null}
95	     * @return the telephone reduced to its canonical E.164 comparison form
96	     */
97	    public String canonicalize(String telephone) {
98	        if (telephone == null) {
99	            return "";
100	        }
101	        boolean hasCountryCode = telephone.trim().startsWith("+");
102	        String digits = telephone.replaceAll("\\D", "");
103	        if (!hasCountryCode) {
104	            if (digits.startsWith("0")) {
105	                digits = digits.substring(1);
106	            }
107	            digits = DEFAULT_COUNTRY_CODE.substring(1) + digits;
108	        }
109	        return "+" + digits;
110	    }
111	}
