19	/**
20	 * Raised when an owner submitted to the create endpoint carries a 4-digit {@code postcode} that is
21	 * out of range for the owner's city region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). The
22	 * malformed (non 4-digit) case is already rejected by Bean Validation's {@code @Pattern} constraint;
23	 * this closes the gap for a well-formed postcode that falls outside the city region's range. The
24	 * {@code ExceptionControllerAdvice} renders it as a 400 response naming the {@code postcode} field.
25	 */
26	public class InvalidOwnerPostcodeException extends RuntimeException {
27	
28	    private final String postcode;
29	
30	    private final String city;
31	
32	    public InvalidOwnerPostcodeException(String postcode, String city) {
33	        super("Postcode '" + postcode + "' is out of range for city '" + city + "'");
34	        this.postcode = postcode;
35	        this.city = city;
36	    }
37	
38	    /**
39	     * @return the rejected postcode
40	     */
41	    public String getPostcode() {
42	        return this.postcode;
43	    }
44	
45	    /**
46	     * @return the city whose region the postcode was out of range for
47	     */
48	    public String getCity() {
49	        return this.city;
50	    }
51	}
