17	
18	import java.util.Map;
19	import java.util.Optional;
20	
21	/**
22	 * The Australian region an owner's city belongs to. Each constant's name is the canonical region
23	 * code as stored and returned (e.g. {@code "NSW"}). Regions are resolved from a single fixed
24	 * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD});
25	 * a city that is not in the table has no known region.
26	 *
27	 * <p>This is the one place the city-to-region mapping lives, so every rule that keys off an owner's
28	 * region - such as the derived {@code locality} - resolves it identically.
29	 */
30	public enum Region {
31	
32	    NSW(2000, 2099),
33	    VIC(3000, 3099),
34	    QLD(4000, 4099);
35	
36	    private final int minPostcode;
37	
38	    private final int maxPostcode;
39	
40	    Region(int minPostcode, int maxPostcode) {
41	        this.minPostcode = minPostcode;
42	        this.maxPostcode = maxPostcode;
43	    }
44	
45	    /** Fixed city -> region table; a city absent from this map has no known region. */
46	    private static final Map<String, Region> BY_CITY = Map.of(
47	        "Sydney", NSW,
48	        "Melbourne", VIC,
49	        "Brisbane", QLD);
50	
51	    /**
52	     * Reports whether the given 4-digit postcode falls within this region's inclusive postcode range
53	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). This is the one place the region-to-postcode
54	     * range lives, so every rule that validates a postcode against an owner's region resolves it
55	     * identically.
56	     *
57	     * @param postcode the numeric value of the owner's 4-digit postcode
58	     * @return {@code true} when the postcode is within this region's range
59	     */
60	    public boolean acceptsPostcode(int postcode) {
61	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
62	    }
63	
64	    /**
65	     * Resolves the region for the given city from the fixed city-to-region table.
66	     *
67	     * @param city the owner's city, or {@code null}
68	     * @return the matching region, or empty when the city is {@code null} or has no known region
69	     */
70	    public static Optional<Region> forCity(String city) {
71	        return city == null ? Optional.empty() : Optional.ofNullable(BY_CITY.get(city));
72	    }
73	
74	    /**
75	     * Resolves the region whose postcode range contains the given 4-digit postcode
76	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
77	     *
78	     * @param postcode the owner's 4-digit postcode, or {@code null}
79	     * @return the matching region, or empty when the postcode is {@code null}, not numeric, or in no
80	     *         known range
81	     */
82	    public static Optional<Region> forPostcode(String postcode) {
83	        if (postcode == null) {
84	            return Optional.empty();
85	        }
86	        int value;
87	        try {
88	            value = Integer.parseInt(postcode.trim());
89	        } catch (NumberFormatException ex) {
90	            return Optional.empty();
91	        }
92	        for (Region region : values()) {
93	            if (region.acceptsPostcode(value)) {
94	                return Optional.of(region);
95	            }
96	        }
97	        return Optional.empty();
98	    }
99	}
